import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("a vendor sent back for a rejected contract can be renamed", { tag: "@LIF-09" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review, then a reviewer rejects its contract extraction
  const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
  const reviewer = await apiAs("reviewer");
  const decision = await expectStatus<{ status: string }>(
    await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
      data: { decision: "reject", note: "Contract signature page is missing." },
    }),
    200,
  );
  expect(decision.status, "contract extraction is rejected").toBe("rejected");

  const newName = uniqueName("Renamed Vendor");
  const member = await apiAs("member");

  // Act: the member changes the vendor's name
  const response = await member.patch(`/api/vendors/${vendor.id}`, { data: { name: newName } });

  // Assert: the response carries the new name
  const updated = await expectStatus<{ id: string; name: string }>(response, 200);
  expect(updated.id).toBe(vendor.id);
  expect(updated.name).toBe(newName);

  // Assert: the stored vendor has the new name
  const stored = await expectStatus<{ name: string }>(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.name).toBe(newName);
});
